        replacement_id
    ):
        raise ServiceError(
            400, "replacement_id must match [A-Za-z0-9_-]{1,128}"
        )

@staticmethod
def _validate_offline_share_id(offline_share_id: object) -> None:
    if not isinstance(offline_share_id, str) or not ROTATION_ID_RE.match(
        offline_share_id
    ):
        raise ServiceError(
